{"version":3,"file":"ride.js","sources":["stores/ride.js"],"sourcesContent":["import { defineStore } from 'pinia'\r\nimport { ref, watch } from 'vue'\r\n\r\nexport const useRideStore = defineStore('ride', () => {\r\n  // 更丰富的全状态 Mock 数据\r\n  const defaultRides = [\r\n    { id: 101, driver: '张师傅', start: '科技园南区', end: '高铁站', time: '14:30', seats: 2, price: 25, status: 'recruiting', lat: 22.543099, lng: 113.938036 },\r\n    { id: 102, driver: '李女士', start: '市中心广场', end: '宝安国际机场', time: '15:00', seats: 3, price: 40, status: 'recruiting', lat: 22.545000, lng: 113.940000 },\r\n    { id: 103, driver: '王大爷', start: '深圳大学', end: '罗湖火车站', time: '16:30', seats: 1, price: 20, status: 'recruiting', lat: 22.535000, lng: 113.930000 },\r\n    { id: 104, driver: '赵哥', start: '前海中心', end: '软件产业基地', time: '17:00', seats: 0, price: 15, status: 'full', lat: 22.530000, lng: 113.920000 },\r\n    { id: 105, driver: '陈姐', start: '欢乐谷', end: '世界之窗', time: '18:00', seats: 2, price: 10, status: 'recruiting', lat: 22.538000, lng: 113.935000 },\r\n    { id: 106, driver: '林同学', start: '大学城', end: '大梅沙', time: '明天 09:00', seats: 3, price: 50, status: 'recruiting', lat: 22.580000, lng: 113.970000 }\r\n  ]\r\n\r\n  const rides = ref([])\r\n  const userOrders = ref([])\r\n\r\n  // 初始化并增加容错处理\r\n  const init = () => {\r\n    try {\r\n      const storedRides = uni.getStorageSync('pc_rides')\r\n      const storedOrders = uni.getStorageSync('pc_orders')\r\n      rides.value = storedRides ? JSON.parse(storedRides) : defaultRides\r\n      userOrders.value = storedOrders ? JSON.parse(storedOrders) : []\r\n    } catch (e) {\r\n      rides.value = defaultRides\r\n      userOrders.value = []\r\n    }\r\n  }\r\n\r\n  // 深度监听，实时持久化\r\n  watch(rides, (newVal) => {\r\n    uni.setStorageSync('pc_rides', JSON.stringify(newVal))\r\n  }, { deep: true })\r\n\r\n  watch(userOrders, (newVal) => {\r\n    uni.setStorageSync('pc_orders', JSON.stringify(newVal))\r\n  }, { deep: true })\r\n\r\n  const publishRide = (rideData) => {\r\n    const newRide = { ...rideData, id: Date.now(), driver: '我(车主)', status: 'recruiting' }\r\n    rides.value.unshift(newRide)\r\n    userOrders.value.unshift({ ...newRide, orderId: `DD${Date.now()}`, orderStatus: '进行中', role: 'driver' })\r\n  }\r\n\r\n  const joinRide = (rideId) => {\r\n    const ride = rides.value.find(r => r.id === rideId)\r\n    if (ride && ride.seats > 0) {\r\n      ride.seats -= 1\r\n      if (ride.seats === 0) ride.status = 'full'\r\n      userOrders.value.unshift({ ...ride, orderId: `DD${Date.now()}`, orderStatus: '已完成', role: 'passenger' })\r\n      return true\r\n    }\r\n    return false\r\n  }\r\n\r\n  return { rides, userOrders, init, publishRide, joinRide }\r\n})"],"names":["defineStore","ref","uni","watch"],"mappings":";;AAGY,MAAC,eAAeA,cAAAA,YAAY,QAAQ,MAAM;AAEpD,QAAM,eAAe;AAAA,IACnB,EAAE,IAAI,KAAK,QAAQ,OAAO,OAAO,SAAS,KAAK,OAAO,MAAM,SAAS,OAAO,GAAG,OAAO,IAAI,QAAQ,cAAc,KAAK,WAAW,KAAK,WAAY;AAAA,IACjJ,EAAE,IAAI,KAAK,QAAQ,OAAO,OAAO,SAAS,KAAK,UAAU,MAAM,SAAS,OAAO,GAAG,OAAO,IAAI,QAAQ,cAAc,KAAK,QAAW,KAAK,OAAY;AAAA,IACpJ,EAAE,IAAI,KAAK,QAAQ,OAAO,OAAO,QAAQ,KAAK,SAAS,MAAM,SAAS,OAAO,GAAG,OAAO,IAAI,QAAQ,cAAc,KAAK,QAAW,KAAK,OAAY;AAAA,IAClJ,EAAE,IAAI,KAAK,QAAQ,MAAM,OAAO,QAAQ,KAAK,UAAU,MAAM,SAAS,OAAO,GAAG,OAAO,IAAI,QAAQ,QAAQ,KAAK,OAAW,KAAK,OAAY;AAAA,IAC5I,EAAE,IAAI,KAAK,QAAQ,MAAM,OAAO,OAAO,KAAK,QAAQ,MAAM,SAAS,OAAO,GAAG,OAAO,IAAI,QAAQ,cAAc,KAAK,QAAW,KAAK,QAAY;AAAA,IAC/I,EAAE,IAAI,KAAK,QAAQ,OAAO,OAAO,OAAO,KAAK,OAAO,MAAM,YAAY,OAAO,GAAG,OAAO,IAAI,QAAQ,cAAc,KAAK,OAAW,KAAK,OAAY;AAAA,EACnJ;AAED,QAAM,QAAQC,cAAG,IAAC,EAAE;AACpB,QAAM,aAAaA,cAAG,IAAC,EAAE;AAGzB,QAAM,OAAO,MAAM;AACjB,QAAI;AACF,YAAM,cAAcC,cAAAA,MAAI,eAAe,UAAU;AACjD,YAAM,eAAeA,cAAAA,MAAI,eAAe,WAAW;AACnD,YAAM,QAAQ,cAAc,KAAK,MAAM,WAAW,IAAI;AACtD,iBAAW,QAAQ,eAAe,KAAK,MAAM,YAAY,IAAI,CAAE;AAAA,IAChE,SAAQ,GAAG;AACV,YAAM,QAAQ;AACd,iBAAW,QAAQ,CAAE;AAAA,IACtB;AAAA,EACF;AAGDC,sBAAM,OAAO,CAAC,WAAW;AACvBD,kBAAG,MAAC,eAAe,YAAY,KAAK,UAAU,MAAM,CAAC;AAAA,EACzD,GAAK,EAAE,MAAM,MAAM;AAEjBC,sBAAM,YAAY,CAAC,WAAW;AAC5BD,kBAAG,MAAC,eAAe,aAAa,KAAK,UAAU,MAAM,CAAC;AAAA,EAC1D,GAAK,EAAE,MAAM,MAAM;AAEjB,QAAM,cAAc,CAAC,aAAa;AAChC,UAAM,UAAU,EAAE,GAAG,UAAU,IAAI,KAAK,IAAG,GAAI,QAAQ,SAAS,QAAQ,aAAc;AACtF,UAAM,MAAM,QAAQ,OAAO;AAC3B,eAAW,MAAM,QAAQ,EAAE,GAAG,SAAS,SAAS,KAAK,KAAK,IAAG,CAAE,IAAI,aAAa,OAAO,MAAM,UAAU;AAAA,EACxG;AAED,QAAM,WAAW,CAAC,WAAW;AAC3B,UAAM,OAAO,MAAM,MAAM,KAAK,OAAK,EAAE,OAAO,MAAM;AAClD,QAAI,QAAQ,KAAK,QAAQ,GAAG;AAC1B,WAAK,SAAS;AACd,UAAI,KAAK,UAAU;AAAG,aAAK,SAAS;AACpC,iBAAW,MAAM,QAAQ,EAAE,GAAG,MAAM,SAAS,KAAK,KAAK,IAAG,CAAE,IAAI,aAAa,OAAO,MAAM,aAAa;AACvG,aAAO;AAAA,IACR;AACD,WAAO;AAAA,EACR;AAED,SAAO,EAAE,OAAO,YAAY,MAAM,aAAa,SAAU;AAC3D,CAAC;;"}
