{"version":3,"file":"ride.js","sources":["stores/ride.js"],"sourcesContent":["import { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\nexport const useRideStore = defineStore('ride', () => {\n  // 默认 Mock 数据，防止云端没数据时页面空白\n  const defaultRides = [\n    { id: 101, driver: '张师傅', start: '科技园南区', end: '高铁站', time: '14:30', seats: 2, price: 25, status: 'recruiting' },\n    { id: 102, driver: '李女士', start: '市中心广场', end: '机场', time: '15:00', seats: 3, price: 40, status: 'recruiting' }\n  ]\n\n  const rides = ref([])\n  const userOrders = ref([])\n\n  // 初始化：从云数据库拉取真实数据\n  const init = async () => {\n    try {\n      const db = wx.cloud.database()\n      // 按创建时间倒序排列，获取最新的行程\n      const res = await db.collection('ride_list').orderBy('createTime', 'desc').get()\n      \n      if (res.data && res.data.length > 0) {\n        rides.value = res.data\n      } else {\n        rides.value = defaultRides\n      }\n    } catch (e) {\n      console.error('初始化获取云端数据失败，使用默认数据', e)\n      rides.value = defaultRides\n    }\n  }\n\n  // 发布行程：将数据真实存入微信云数据库 ride_list\n  const publishRide = async (rideData) => {\n    try {\n      const db = wx.cloud.database()\n      const newRide = { \n        ...rideData, \n        driver: '我(车主)', \n        status: 'recruiting',\n        createTime: db.serverDate() // 使用服务器时间，避免手机时间不对导致校验失败\n      }\n\n      // 1. 核心步骤：向云数据库添加记录\n      const res = await db.collection('ride_list').add({\n        data: newRide\n      })\n      \n      // 2. 将新数据同步到本地显示的列表中\n      const rideWithId = { ...newRide, id: res._id }\n      rides.value.unshift(rideWithId)\n      userOrders.value.unshift({ ...rideWithId, orderId: `DD${Date.now()}`, orderStatus: '进行中', role: 'driver' })\n      \n      return true \n    } catch (e) {\n      console.error('存入云数据库失败：', e)\n      return false\n    }\n  }\n\n  const joinRide = (rideId) => {\n    const ride = rides.value.find(r => r.id === rideId)\n    if (ride && ride.seats > 0) {\n      ride.seats -= 1\n      if (ride.seats === 0) ride.status = 'full'\n      return true\n    }\n    return false\n  }\n\n  return { rides, userOrders, init, publishRide, joinRide }\n})"],"names":["defineStore","ref","wx","uni"],"mappings":";;AAGY,MAAC,eAAeA,cAAAA,YAAY,QAAQ,MAAM;AAEpD,QAAM,eAAe;AAAA,IACnB,EAAE,IAAI,KAAK,QAAQ,OAAO,OAAO,SAAS,KAAK,OAAO,MAAM,SAAS,OAAO,GAAG,OAAO,IAAI,QAAQ,aAAc;AAAA,IAChH,EAAE,IAAI,KAAK,QAAQ,OAAO,OAAO,SAAS,KAAK,MAAM,MAAM,SAAS,OAAO,GAAG,OAAO,IAAI,QAAQ,aAAc;AAAA,EAChH;AAED,QAAM,QAAQC,cAAG,IAAC,EAAE;AACpB,QAAM,aAAaA,cAAG,IAAC,EAAE;AAGzB,QAAM,OAAO,YAAY;AACvB,QAAI;AACF,YAAM,KAAKC,cAAAA,KAAG,MAAM,SAAU;AAE9B,YAAM,MAAM,MAAM,GAAG,WAAW,WAAW,EAAE,QAAQ,cAAc,MAAM,EAAE,IAAK;AAEhF,UAAI,IAAI,QAAQ,IAAI,KAAK,SAAS,GAAG;AACnC,cAAM,QAAQ,IAAI;AAAA,MAC1B,OAAa;AACL,cAAM,QAAQ;AAAA,MACf;AAAA,IACF,SAAQ,GAAG;AACVC,oBAAAA,MAAA,MAAA,SAAA,wBAAc,sBAAsB,CAAC;AACrC,YAAM,QAAQ;AAAA,IACf;AAAA,EACF;AAGD,QAAM,cAAc,OAAO,aAAa;AACtC,QAAI;AACF,YAAM,KAAKD,cAAAA,KAAG,MAAM,SAAU;AAC9B,YAAM,UAAU;AAAA,QACd,GAAG;AAAA,QACH,QAAQ;AAAA,QACR,QAAQ;AAAA,QACR,YAAY,GAAG,WAAY;AAAA;AAAA,MAC5B;AAGD,YAAM,MAAM,MAAM,GAAG,WAAW,WAAW,EAAE,IAAI;AAAA,QAC/C,MAAM;AAAA,MACd,CAAO;AAGD,YAAM,aAAa,EAAE,GAAG,SAAS,IAAI,IAAI,IAAK;AAC9C,YAAM,MAAM,QAAQ,UAAU;AAC9B,iBAAW,MAAM,QAAQ,EAAE,GAAG,YAAY,SAAS,KAAK,KAAK,IAAG,CAAE,IAAI,aAAa,OAAO,MAAM,UAAU;AAE1G,aAAO;AAAA,IACR,SAAQ,GAAG;AACVC,oBAAAA,MAAc,MAAA,SAAA,wBAAA,aAAa,CAAC;AAC5B,aAAO;AAAA,IACR;AAAA,EACF;AAED,QAAM,WAAW,CAAC,WAAW;AAC3B,UAAM,OAAO,MAAM,MAAM,KAAK,OAAK,EAAE,OAAO,MAAM;AAClD,QAAI,QAAQ,KAAK,QAAQ,GAAG;AAC1B,WAAK,SAAS;AACd,UAAI,KAAK,UAAU;AAAG,aAAK,SAAS;AACpC,aAAO;AAAA,IACR;AACD,WAAO;AAAA,EACR;AAED,SAAO,EAAE,OAAO,YAAY,MAAM,aAAa,SAAU;AAC3D,CAAC;;"}
